Definition shc_seg2_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (E PC q lo : Z) (junkB : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' j7,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 q) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(bv_unsigned sp + -48, bv_unsigned sp); (PC, PC + 8); (q, q + 32)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' PC [C8 (Z_to_bv 64 q)]
    /\ rw_cells asegs m' q (SpcHdrCells (mkSPC (shc_vp E) 1 1 0) j7)
    /\ rw_cells asegs m' (q + 32) [CB (Z.to_nat (shc_size E - 32)) (skipn 32 junkB)].

Lemma shc_seg2 : forall (E : Z), shc_entry_ok E ->
  forall (pcv rax sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (s3v s2v s1v s0v rav : word)
    (F : bvmap 5 word) fc (m : mem) (PC q lo shi : Z) (junkF junkB : list byte),
  (pcv = Z_to_bv 64 (E + 0x48) \/ pcv = ret_pc (Z_to_bv 64 (E + 0x48))) ->
  rw_cells asegs m (bv_unsigned sp + -48) (shc_frame s3v s2v s1v s0v rav junkF) ->
  rw_cells asegs m PC [C8 (Z_to_bv 64 0)] -> bv_unsigned sp <= PC -> PC + 8 <= shi -> PC mod 8 = 0 ->
  rw_cells asegs m q [CB (Z.to_nat (shc_size E)) junkB] -> addressable m q (shc_size E) ->
  rblock_range q (shc_size E) ->
  stk asegs m lo (bv_unsigned sp + -48) -> lo + 48 <= bv_unsigned sp -> aceil <= lo ->
  mem_inv asegs m -> ACONST m -> stack0 m lo shi ->
  evt asegs (shc_seg2_post rav sp gp tp s0v s1v s2v s3v s4 s5 s6 s7 s8 s9 s10 s11 F fc E PC q lo junkB m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2
             (Z_to_bv 64 PC) (Z_to_bv 64 0) (Z_to_bv 64 q) a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 (Z.shiftr PC 3 + 2147450880)) (Z_to_bv 64 2147450880) s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F pcv fc None m (seg_rom asegs)).
